/// @brief Supported HTTP request methods.
enum class HttpVerb {
    Get,     ///< Retrieves a representation.
    Post,    ///< Submits a representation.
    Put,     ///< Replaces a representation.
    Delete,  ///< Removes a representation.
    Patch,   ///< Partially updates a representation.
    Head,    ///< Retrieves response metadata without a response body.
    Options, ///< Retrieves communication options.
};

/// @brief Supported encodings for a flat HTTP parameter collection.
enum class CollectionEncoding {
    Repeated,       ///< Repeats the parameter name once per element, matching form/explode query defaults.
    CommaSeparated, ///< Joins elements with commas, matching simple header defaults.
    SpaceSeparated, ///< Joins elements with spaces before URL encoding.
    PipeSeparated,  ///< Joins elements with vertical bars before URL encoding.
};

/// @brief Owns unencoded query components and preserves collection boundaries until URL construction.
struct QueryParameter {
    std::string Name; ///< Original wire name, percent-encoded only by the transport.
    std::vector<std::string> Values; ///< Independently unencoded scalar or collection element values.
    CollectionEncoding Encoding = CollectionEncoding::Repeated; ///< Collection separators inserted after each element is encoded.
};

/// @brief Owns a complete request so its body can be replayed after an explicitly authorized retry.
struct Request {
    /// @brief Owns one multipart file, including the bytes retained for retries.
    struct FilePart {
        std::string FieldName;             ///< Original multipart field name.
        std::string FileName;              ///< File name transmitted to the server.
        std::vector<unsigned char> Bytes;  ///< Complete file payload.
        std::string MimeType;              ///< Media type, defaulting to application/octet-stream.
    };

    HttpVerb Verb = HttpVerb::Get; ///< HTTP request method.
    std::string Path; ///< Path relative to the configured base URL.
    std::vector<QueryParameter> Query; ///< Owned query components with explicit collection encoding.
    std::vector<std::pair<std::string, std::string>> Headers; ///< Request headers, including repeated values.
    std::string Body; ///< Owned request body before form encoding.
    std::string ContentType; ///< Request body media type.
    std::vector<FilePart> FileParts; ///< Owned multipart file parts.
    std::vector<std::pair<std::string, std::string>> FormFields; ///< Unencoded form field names and values.

{{RequestParameterRuntimeTemplates.Declarations()}}
    /// @brief Stores independently unencoded query elements without losing literal delimiter characters.
    /// @param name Original wire name.
    /// @param values Complete scalar or flat collection elements owned by the request.
    /// @param encoding Collection separators used after each element is percent-encoded.
    /// @throws std::invalid_argument If encoding is not a supported collection mode.
    void AddQueryValues(std::string name, std::vector<std::string> values, CollectionEncoding encoding);
    /// @brief Replaces all case-insensitive matches with exactly one header value.
    /// @param name Header name, for example Authorization.
    /// @param value New header value, for example Bearer followed by a refreshed token.
    void SetHeader(std::string name, std::string value);
    /// @brief Removes every case-insensitive match for a header name.
    /// @param name Header name to remove.
    void RemoveHeader(std::string_view name);
    /// @brief Replaces the body with JSON and clears previously configured form data.
    /// @param body Serialized JSON document.
    void SetJsonBody(std::string body);
    /// @brief Replaces the body with form fields and clears multipart files.
    /// @param fields Unencoded form fields.
    void SetFormBody(const std::vector<std::pair<std::string, std::string>>& fields);
    /// @brief Appends an owned multipart file that remains replayable.
    /// @param fieldName Original multipart field name.
    /// @param fileName File name sent to the server.
    /// @param bytes Complete file bytes copied into the request.
    /// @param mimeType File media type.
    void AddFilePart(std::string fieldName, std::string fileName, const std::vector<unsigned char>& bytes, std::string mimeType);
};

/// @brief Owns the raw response before generated status and JSON decoding checks.
struct Response {
    int StatusCode = 0; ///< Received HTTP status code.
    std::string Body; ///< Raw response body, retained for diagnostics.
    std::vector<std::pair<std::string, std::string>> Headers; ///< Response headers, including repeated values.
};

/// @brief Explicit interception and response-based retry policy.
/// @details Hooks execute outside the connection mutex and may call the same HttpClient to refresh authentication.
/// They run for each attempt in BeforeSend, AfterReceive, ShouldRetry order. A hook may modify the owned request
/// or response. Callers must synchronize any state captured by hooks used concurrently. No request is logged by default.
/// Retries can repeat server-side effects: enable them only when the request is safe to replay.
struct RequestPipeline {
    /// @brief Updates request headers, query parameters, path, or body immediately before each attempt.
    std::function<void(Request&, const CancellationToken&)> BeforeSend;
    /// @brief Observes or transforms every received response, including failures such as HTTP 401.
    std::function<void(const Request&, Response&, const CancellationToken&)> AfterReceive;
    /// @brief Authorizes another attempt and may update the request after refreshing authentication.
    /// @details The third argument counts already completed retries, starting at zero. Transport failures and
    /// cancellations do not invoke this hook. Returning true has no effect once MaxRetries has been reached.
    std::function<bool(Request&, const Response&, std::size_t, const CancellationToken&)> ShouldRetry;
    std::size_t MaxRetries = 0; ///< Maximum additional attempts; zero disables retries even when a hook exists.
};

/// @brief Connection settings and application-owned request policy copied into a reusable transport.
struct HttpConfig {
    std::string BaseUrl; ///< HTTP or HTTPS origin with an optional base path.
    int ConnectTimeoutSeconds = 5; ///< Connection establishment timeout; operating system DNS resolution is separate.
    int ReadTimeoutSeconds = 30; ///< Read inactivity timeout; an HTTPS cancellation may wait for the upstream SSL read to finish or time out.
    bool KeepAlive = true; ///< Reuse the persistent connection when the server permits it.
    std::string ProxyHost; ///< Optional proxy host.
    int ProxyPort = 0; ///< Proxy port used when ProxyHost is nonempty.
    std::vector<std::pair<std::string, std::string>> DefaultHeaders; ///< Defaults used only when a request has no matching header.
    RequestPipeline Pipeline; ///< Optional hooks and explicit bounded retry policy.
};

/// @brief Percent-encodes query, form, or path values using RFC 3986 unreserved characters.
/// @param value Unencoded bytes.
/// @return Percent-encoded bytes suitable for insertion into a URL.
std::string UrlEncode(const std::string& value);

/// @brief Replaces every occurrence of one validated route placeholder.
/// @param path The route being expanded.
/// @param placeholder The complete placeholder, including its braces.
/// @param encodedValue The already percent-encoded parameter value.
void ReplacePathParameter(std::string& path, std::string_view placeholder, const std::string& encodedValue);

/// @brief Retains an unsuccessful status and its unparsed response body.
/// @param statusCode Received HTTP status code.
/// @param body Raw response body.
/// @return A status error suitable for returning before JSON parsing.
Error ErrorFromStatus(int statusCode, const std::string& body);

/// @brief Reusable HTTP transport with synchronized network dispatch and reentrant interception hooks.
/// @details A shared_ptr safely retains this transport across generated clients and outstanding futures.
/// A cancelled queued request never acquires the connection. An active cancellation stops only that request's
/// socket subscription, which is detached before another request can use the connection. Cancelling a request
/// does not establish whether the server has already processed it. Moving or destroying a client concurrently
/// with Send is unsupported; retain shared ownership until all calls have finished.
/// Plain HTTP reads and writes poll cancellation without shortening their configured inactivity deadlines.
/// HTTPS uses the pinned cpp-httplib SSLClient through its public API because that class is final and exposes no
/// replaceable stream. Its stop and response/progress callbacks request cancellation safely, but an operating system
/// or OpenSSL read may finish only when data arrives or ReadTimeoutSeconds expires. Immediate HTTPS read cancellation
/// is therefore not guaranteed. Connection establishment and TLS handshake follow the transport's connection timeout;
/// DNS lookup follows the operating system resolver. A cancelled result does not authorize an automatic retry.
class HttpClient {
public:
    /// @brief Creates a transport using the default configuration.
    HttpClient();
    /// @brief Creates a transport from an owned copy of the supplied configuration.
    /// @param config Base URL, timeouts, connection reuse, proxy, headers, and hooks.
    explicit HttpClient(HttpConfig config);
    /// @brief Releases the transport and its persistent connection after outstanding calls have finished.
    ~HttpClient();
    /// @brief Transfers transport ownership without copying a connection.
    /// @param other Transport whose ownership is transferred.
    HttpClient(HttpClient&& other) noexcept;
    /// @brief Replaces this transport with another transport's ownership.
    /// @param other Transport whose ownership is transferred.
    /// @return This client after ownership transfer.
    HttpClient& operator=(HttpClient&& other) noexcept;
    HttpClient(const HttpClient&) = delete; ///< Copying connection ownership is prohibited; use shared_ptr instead.
    HttpClient& operator=(const HttpClient&) = delete; ///< Copying connection ownership is prohibited.

    /// @brief Returns immutable connection and interception settings.
    /// @return The configuration retained for the lifetime of this non-moved-from client.
    /// @throws std::logic_error If this client has been moved from.
    const HttpConfig& GetConfig() const;
    /// @brief Sends an owned copy of the request through hooks and explicitly bounded retries.
    /// @param request Request borrowed only while its replayable copy is created.
    /// @param cancellationToken Optional cancellation signal retained for this entire call.
    /// @return A raw HTTP response, cancellation, interception failure, or transport error.
    Expected<Response, Error> Send(const Request& request, CancellationToken cancellationToken = {}) const;

private:
    struct Impl;
    std::unique_ptr<Impl> _impl;
};

