struct ParsedUrl {
    std::string Scheme;
    std::string Host;
    std::string Port;
    std::string BasePath;
};

ParsedUrl ParseBaseUrl(const std::string& url) {
    ParsedUrl parsed;
    std::string rest = url;
    const std::size_t schemeEnd = url.find("://");
    if (schemeEnd != std::string::npos) {
        parsed.Scheme = url.substr(0, schemeEnd);
        rest = url.substr(schemeEnd + 3);
    } else {
        parsed.Scheme = "http";
    }
    const std::size_t pathStart = rest.find('/');
    const std::string hostPort = pathStart == std::string::npos ? rest : rest.substr(0, pathStart);
    parsed.BasePath = pathStart == std::string::npos ? std::string() : rest.substr(pathStart);
    if (!hostPort.empty() && hostPort.front() == '[') {
        const auto bracket = hostPort.find(']');
        if (bracket == std::string::npos) {
            return parsed;
        }
        parsed.Host = hostPort.substr(0, bracket + 1);
        if (bracket + 1 < hostPort.size()) {
            if (hostPort[bracket + 1] != ':') {
                parsed.Host.clear();
            } else {
                parsed.Port = hostPort.substr(bracket + 2);
            }
        }
    } else {
        const std::size_t portStart = hostPort.find(':');
        parsed.Host = hostPort.substr(0, portStart);
        if (portStart != std::string::npos) {
            parsed.Port = hostPort.substr(portStart + 1);
        }
    }
    return parsed;
}

bool HeaderNamesEqual(const std::string_view left, const std::string_view right) {
    if (left.size() != right.size()) {
        return false;
    }
    for (std::size_t index = 0; index < left.size(); ++index) {
        const auto lower = [](const char value) { return value >= 'A' && value <= 'Z' ? value + ('a' - 'A') : value; };
        if (lower(left[index]) != lower(right[index])) {
            return false;
        }
    }
    return true;
}

bool IsHeaderName(const std::string& name) {
    return !name.empty() && std::all_of(name.begin(), name.end(), [](const unsigned char character) {
        return (character >= 'A' && character <= 'Z') || (character >= 'a' && character <= 'z')
            || (character >= '0' && character <= '9') || std::string_view("!#$%&'*+-.^_`|~").find(static_cast<char>(character)) != std::string_view::npos;
    });
}

bool HasLineBreakOrNull(const std::string& value) {
    return value.find_first_of("\r\n") != std::string::npos || value.find('\0') != std::string::npos;
}

std::string AppendQuery(const std::string& path, const std::vector<QueryParameter>& query) {
    std::string target = path;
    bool hasQuery = target.find('?') != std::string::npos;
    const auto appendName = [&](const std::string& name) {
        target += hasQuery ? '&' : '?';
        hasQuery = true;
        target += UrlEncode(name);
        target += '=';
    };
    for (const auto& parameter : query) {
        if (parameter.Encoding != CollectionEncoding::Repeated && parameter.Encoding != CollectionEncoding::CommaSeparated
            && parameter.Encoding != CollectionEncoding::SpaceSeparated && parameter.Encoding != CollectionEncoding::PipeSeparated)
            throw std::invalid_argument("Unknown HTTP collection encoding");
        if (parameter.Encoding == CollectionEncoding::Repeated) {
            for (const auto& value : parameter.Values) {
                appendName(parameter.Name);
                target += UrlEncode(value);
            }
            continue;
        }
        appendName(parameter.Name);
        const std::string_view separator = parameter.Encoding == CollectionEncoding::CommaSeparated ? ","
            : parameter.Encoding == CollectionEncoding::SpaceSeparated ? "%20" : "%7C";
        bool first = true;
        for (const auto& value : parameter.Values) {
            if (!first) target += separator;
            target += UrlEncode(value);
            first = false;
        }
    }
    return target;
}

const char* VerbName(const HttpVerb verb) {
    switch (verb) {
    case HttpVerb::Get: return "GET";
    case HttpVerb::Post: return "POST";
    case HttpVerb::Put: return "PUT";
    case HttpVerb::Delete: return "DELETE";
    case HttpVerb::Patch: return "PATCH";
    case HttpVerb::Head: return "HEAD";
    case HttpVerb::Options: return "OPTIONS";
    }
    throw std::invalid_argument("Unsupported HTTP verb");
}

Error CancelledError() {
    Error error;
    error.What = Error::Code::Cancelled;
    error.Message = "Request cancelled";
    return error;
}

std::string EncodeFormFields(const std::vector<std::pair<std::string, std::string>>& fields) {
    std::string body;
    for (std::size_t i = 0; i < fields.size(); ++i) {
        if (i != 0) {
            body += '&';
        }
        body += UrlEncode(fields[i].first) + '=' + UrlEncode(fields[i].second);
    }
    return body;
}

std::string EscapePartName(const std::string& value) {
    std::string escaped;
    for (const char character : value) {
        if (character == '\r') {
            escaped += "%0D";
        } else if (character == '\n') {
            escaped += "%0A";
        } else {
            if (character == '\\' || character == '"') {
                escaped += '\\';
            }
            escaped += character;
        }
    }
    return escaped;
}

std::string EncodeMultipartBody(const Request& request, std::string& contentType) {
    std::string boundary = "----ValIOBoundary";
    for (;;) {
        bool collision = false;
        for (const auto& field : request.FormFields) {
            collision = collision || field.first.find(boundary) != std::string::npos || field.second.find(boundary) != std::string::npos;
        }
        for (const auto& part : request.FileParts) {
            const std::string bytes(part.Bytes.begin(), part.Bytes.end());
            collision = collision || bytes.find(boundary) != std::string::npos || part.FieldName.find(boundary) != std::string::npos
                || part.FileName.find(boundary) != std::string::npos || part.MimeType.find(boundary) != std::string::npos;
        }
        if (!collision) {
            break;
        }
        boundary += '_';
    }
    contentType = "multipart/form-data; boundary=" + boundary;
    std::string body;
    for (const auto& field : request.FormFields) {
        body += "--" + boundary + "\r\nContent-Disposition: form-data; name=\"" + EscapePartName(field.first) + "\"\r\n\r\n" + field.second + "\r\n";
    }
    for (const auto& part : request.FileParts) {
        const auto mime = part.MimeType.empty() ? std::string("application/octet-stream") : part.MimeType;
        if (mime.find_first_of("\r\n") != std::string::npos) {
            throw std::invalid_argument("Multipart media type contains a line break");
        }
        body += "--" + boundary + "\r\nContent-Disposition: form-data; name=\"" + EscapePartName(part.FieldName)
            + "\"; filename=\"" + EscapePartName(part.FileName) + "\"\r\nContent-Type: " + mime + "\r\n\r\n";
        body.append(part.Bytes.begin(), part.Bytes.end());
        body += "\r\n";
    }
    return body + "--" + boundary + "--\r\n";
}

// A short readiness wait is necessary on Windows: shutdown alone need not wake an existing select call.
class CancellationAwareStream final : public httplib::Stream {
public:
    CancellationAwareStream(httplib::Stream& stream, CancellationToken token,
                            std::chrono::microseconds readTimeout, std::chrono::microseconds writeTimeout)
        : _stream(stream), _token(std::move(token)), _readTimeout(readTimeout), _writeTimeout(writeTimeout) {}

    bool is_readable() const override { return WaitReady(true, std::chrono::steady_clock::now() + _readTimeout); }
    bool is_writable() const override { return WaitReady(false, std::chrono::steady_clock::now() + _writeTimeout); }

    ssize_t read(char* target, const std::size_t size) override {
        const auto deadline = std::chrono::steady_clock::now() + _readTimeout;
        for (;;) {
            if (_token.IsCancellationRequested()) return -1;
            // Consume the underlying stream's buffered bytes before waiting for new socket activity.
            const auto result = _stream.read(target, size);
            if (result >= 0) return result;
            if (!WaitReady(true, deadline)) return -1;
            if (!httplib::detail::is_socket_alive(_stream.socket())) return -1;
        }
    }

    ssize_t write(const char* source, const std::size_t size) override {
        const auto deadline = std::chrono::steady_clock::now() + _writeTimeout;
        for (;;) {
            if (_token.IsCancellationRequested()) return -1;
            const auto result = _stream.write(source, size);
            if (result >= 0) return result;
            if (!WaitReady(false, deadline)) return -1;
            if (!httplib::detail::is_socket_alive(_stream.socket())) return -1;
        }
    }

    void get_remote_ip_and_port(std::string& ip, int& port) const override { _stream.get_remote_ip_and_port(ip, port); }
    void get_local_ip_and_port(std::string& ip, int& port) const override { _stream.get_local_ip_and_port(ip, port); }
    socket_t socket() const override { return _stream.socket(); }

private:
    bool WaitReady(const bool reading, const std::chrono::steady_clock::time_point deadline) const {
        for (;;) {
            if (_token.IsCancellationRequested()) return false;
            const auto now = std::chrono::steady_clock::now();
            if (now >= deadline) return false;
            const auto remaining = std::chrono::duration_cast<std::chrono::microseconds>(deadline - now);
            const auto slice = (std::min)(remaining, std::chrono::microseconds(10000));
            const auto ready = reading ? httplib::detail::select_read(_stream.socket(), 0, static_cast<time_t>(slice.count()))
                : httplib::detail::select_write(_stream.socket(), 0, static_cast<time_t>(slice.count()));
            if (ready > 0) return !_token.IsCancellationRequested();
            if (ready < 0) return false;
        }
    }

    httplib::Stream& _stream;
    CancellationToken _token;
    std::chrono::microseconds _readTimeout;
    std::chrono::microseconds _writeTimeout;
};

class NonblockingSocketScope {
public:
    explicit NonblockingSocketScope(const socket_t socket) : _socket(socket) { httplib::detail::set_nonblocking(_socket, true); }
    ~NonblockingSocketScope() { httplib::detail::set_nonblocking(_socket, false); }
    NonblockingSocketScope(const NonblockingSocketScope&) = delete;
    NonblockingSocketScope& operator=(const NonblockingSocketScope&) = delete;
private:
    socket_t _socket;
};

class CancellationAwareClient final : public httplib::ClientImpl {
public:
    using httplib::ClientImpl::ClientImpl;
    CancellationToken Token;

protected:
    bool process_socket(const Socket& socket, std::function<bool(httplib::Stream&)> callback) override {
        const NonblockingSocketScope nonblocking(socket.sock);
        const auto readTimeout = std::chrono::seconds(this->read_timeout_sec_) + std::chrono::microseconds(this->read_timeout_usec_);
        const auto writeTimeout = std::chrono::seconds(this->write_timeout_sec_) + std::chrono::microseconds(this->write_timeout_usec_);
        httplib::detail::SocketStream stream(socket.sock, 0, 0, 0, 0);
        CancellationAwareStream cancellable(stream, Token, readTimeout, writeTimeout);
        return callback(cancellable);
    }
};

