struct HttpClient::Impl {
    std::timed_mutex SendMutex;
    HttpConfig Config;
    std::string Scheme;
    std::string Host;
    std::string Port;
    std::string BasePath;
    std::unique_ptr<httplib::ClientImpl> Client;
    std::function<void(CancellationToken)> SetCancellationToken;

    void EnsureClient() {
        if (Client) {
            return;
        }
        std::size_t consumed = 0;
        const int port = Port.empty() ? (Scheme == "https" ? 443 : 80) : std::stoi(Port, &consumed);
        if (!Port.empty() && (consumed != Port.size() || Port.front() < '0' || Port.front() > '9')) {
            throw std::invalid_argument("HTTP port must contain decimal digits only");
        }
        if (port < 1 || port > 65535) {
            throw std::invalid_argument("HTTP port must be between 1 and 65535");
        }
#if defined(CPPHTTPLIB_OPENSSL_SUPPORT)
        if (Scheme == "https") {
            Client = std::make_unique<httplib::SSLClient>(Host, port);
            SetCancellationToken = {};
        } else
#endif
        {
            auto plain = std::make_unique<CancellationAwareClient>(Host, port);
            auto& instance = *plain;
            SetCancellationToken = [&instance](CancellationToken token) { instance.Token = std::move(token); };
            Client = std::move(plain);
        }
        Client->set_connection_timeout(Config.ConnectTimeoutSeconds);
        Client->set_read_timeout(Config.ReadTimeoutSeconds);
        Client->set_keep_alive(Config.KeepAlive);
        // The request target is encoded before query collection separators are inserted.
        Client->set_url_encode(false);
        if (!Config.ProxyHost.empty()) {
            Client->set_proxy(Config.ProxyHost, Config.ProxyPort);
        }
    }

    Expected<Response, Error> Dispatch(const Request& request, const CancellationToken& cancellationToken) {
        std::unique_lock<std::timed_mutex> guard(SendMutex, std::defer_lock);
        while (!guard.try_lock_for(std::chrono::milliseconds(10))) {
            if (cancellationToken.IsCancellationRequested()) {
                return MakeError<Response>(CancelledError());
            }
        }
        if (cancellationToken.IsCancellationRequested()) {
            return MakeError<Response>(CancelledError());
        }
#if !defined(CPPHTTPLIB_OPENSSL_SUPPORT)
        if (Scheme == "https") {
            Error error;
            error.What = Error::Code::Unsupported;
            error.Message = "HTTPS requires a cpp-httplib build with CPPHTTPLIB_OPENSSL_SUPPORT";
            return MakeError<Response>(error);
        }
#endif
        if (Host.empty() || (Scheme != "http" && Scheme != "https")) {
            Error error;
            error.What = Error::Code::Transport;
            error.Message = "Invalid HTTP base URL";
            return MakeError<Response>(error);
        }
        try {
            EnsureClient();
            if (SetCancellationToken) SetCancellationToken(cancellationToken);
            httplib::Request wire;
            wire.method = VerbName(request.Verb);
            const std::string path = BasePath + request.Path;
            if (path.empty() || path.front() != '/' || HasLineBreakOrNull(path)) {
                throw std::invalid_argument("HTTP request path must be an absolute path without line breaks or null bytes");
            }
            wire.path = AppendQuery(httplib::detail::encode_url(path), request.Query);
            wire.body = request.Body;
            std::string contentType = request.ContentType;
            const bool multipart = request.ContentType == "multipart/form-data" || !request.FileParts.empty();
            const bool form = !multipart && wire.body.empty() && !request.FormFields.empty();
            if (multipart) {
                wire.body = EncodeMultipartBody(request, contentType);
            } else if (form) {
                wire.body = EncodeFormFields(request.FormFields);
                contentType = "application/x-www-form-urlencoded";
            }
            if (HasLineBreakOrNull(contentType)) {
                throw std::invalid_argument("HTTP media type contains a line break or null byte");
            }
            for (const auto& header : request.Headers) {
                if (!IsHeaderName(header.first) || HasLineBreakOrNull(header.second)) {
                    throw std::invalid_argument("HTTP header name or value is invalid");
                }
                if (HeaderNamesEqual(header.first, "Transfer-Encoding")) {
                    throw std::invalid_argument("Transfer-Encoding is transport-owned for replayable request bodies");
                }
                // Body framing and encoded form media types are derived from the actual bytes after hooks run.
                if (!HeaderNamesEqual(header.first, "Content-Length")
                    && !((multipart || form) && HeaderNamesEqual(header.first, "Content-Type"))) {
                    wire.set_header(header.first, header.second);
                }
            }
            if (!contentType.empty() && !wire.has_header("Content-Type")) {
                wire.set_header("Content-Type", contentType);
            }
            if (contentType == "application/json" && !wire.has_header("Accept")) {
                wire.set_header("Accept", "application/json");
            }
            wire.response_handler = [cancellationToken](const httplib::Response&) { return !cancellationToken.IsCancellationRequested(); };
            wire.progress = [cancellationToken](std::uint64_t, std::uint64_t) { return !cancellationToken.IsCancellationRequested(); };
            // This subscription is destroyed before guard, so a late Cancel cannot stop the next request's socket.
            const detail::CancellationRegistration registration(cancellationToken, [this]() { Client->stop(); });
            if (cancellationToken.IsCancellationRequested()) {
                return MakeError<Response>(CancelledError());
            }
            const auto result = Client->send(wire);
            if (cancellationToken.IsCancellationRequested()) {
                return MakeError<Response>(CancelledError());
            }
            if (!result) {
                Error error;
                error.What = result.error() == httplib::Error::ConnectionTimeout ? Error::Code::Timeout : Error::Code::Transport;
                error.Message = httplib::to_string(result.error());
                return MakeError<Response>(error);
            }
            Response response;
            response.StatusCode = result->status;
            response.Body = result->body;
            response.Headers.assign(result->headers.begin(), result->headers.end());
            return response;
        } catch (const std::exception& exception) {
            Error error;
            error.What = Error::Code::Transport;
            error.Message = exception.what();
            return MakeError<Response>(error);
        }
    }
};

