void Request::AddQueryValues(std::string name, std::vector<std::string> values, const CollectionEncoding encoding) {
    if (encoding != CollectionEncoding::Repeated && encoding != CollectionEncoding::CommaSeparated
        && encoding != CollectionEncoding::SpaceSeparated && encoding != CollectionEncoding::PipeSeparated)
        throw std::invalid_argument("Unknown HTTP collection encoding");
    if (values.empty() && encoding == CollectionEncoding::Repeated) return;
    Query.push_back(QueryParameter{std::move(name), std::move(values), encoding});
}

void Request::SetJsonBody(std::string body) {
    Body = std::move(body);
    ContentType = "application/json";
    FormFields.clear();
    FileParts.clear();
}

void Request::RemoveHeader(const std::string_view name) {
    Headers.erase(std::remove_if(Headers.begin(), Headers.end(), [name](const auto& entry) { return HeaderNamesEqual(entry.first, name); }), Headers.end());
}

void Request::SetHeader(std::string name, std::string value) {
    RemoveHeader(name);
    AddHeader(std::move(name), std::move(value));
}

void Request::SetFormBody(const std::vector<std::pair<std::string, std::string>>& fields) {
    FormFields = fields;
    Body.clear();
    FileParts.clear();
    ContentType = "application/x-www-form-urlencoded";
}

void Request::AddFilePart(std::string fieldName, std::string fileName, const std::vector<unsigned char>& bytes, std::string mimeType) {
    FilePart part;
    part.FieldName = std::move(fieldName);
    part.FileName = std::move(fileName);
    part.Bytes = bytes;
    part.MimeType = std::move(mimeType);
    FileParts.push_back(std::move(part));
}

std::string UrlEncode(const std::string& value) {
    static const char* const HexDigits = "0123456789ABCDEF";
    std::string encoded;
    encoded.reserve(value.size() * 3);
    for (const char character : value) {
        const auto byte = static_cast<unsigned char>(character);
        const bool unreserved = (byte >= 'A' && byte <= 'Z') || (byte >= 'a' && byte <= 'z') || (byte >= '0' && byte <= '9')
            || byte == '-' || byte == '_' || byte == '.' || byte == '~';
        if (unreserved) {
            encoded += character;
        } else {
            encoded += '%';
            encoded += HexDigits[byte >> 4];
            encoded += HexDigits[byte & 0x0F];
        }
    }
    return encoded;
}

void ReplacePathParameter(std::string& path, const std::string_view placeholder, const std::string& encodedValue) {
    if (placeholder.empty()) {
        return;
    }
    std::size_t position = 0;
    while ((position = path.find(placeholder, position)) != std::string::npos) {
        path.replace(position, placeholder.size(), encodedValue);
        position += encodedValue.size();
    }
}

Error ErrorFromStatus(const int statusCode, const std::string& body) {
    Error error;
    error.What = Error::Code::Status;
    error.StatusCode = statusCode;
    error.Message = "HTTP status " + std::to_string(statusCode);
    error.Body = body;
    return error;
}

HttpClient::HttpClient() : HttpClient(HttpConfig{}) {}

HttpClient::HttpClient(HttpConfig config) : _impl(std::make_unique<Impl>()) {
    _impl->Config = std::move(config);
    const auto parsed = ParseBaseUrl(_impl->Config.BaseUrl);
    _impl->Scheme = parsed.Scheme;
    _impl->Host = parsed.Host;
    _impl->Port = parsed.Port;
    _impl->BasePath = parsed.BasePath;
}

HttpClient::~HttpClient() = default;
HttpClient::HttpClient(HttpClient&& other) noexcept = default;
HttpClient& HttpClient::operator=(HttpClient&& other) noexcept = default;

const HttpConfig& HttpClient::GetConfig() const {
    if (!_impl) {
        throw std::logic_error("HTTP client has been moved from");
    }
    return _impl->Config;
}

Expected<Response, Error> HttpClient::Send(const Request& request, CancellationToken cancellationToken) const {
    if (!_impl) {
        Error error;
        error.What = Error::Code::Transport;
        error.Message = "HTTP client has been moved from";
        return MakeError<Response>(error);
    }
    if (cancellationToken.IsCancellationRequested()) {
        return MakeError<Response>(CancelledError());
    }
    Request current = request;
    for (const auto& header : _impl->Config.DefaultHeaders) {
        const bool present = std::any_of(current.Headers.begin(), current.Headers.end(), [&](const auto& entry) { return HeaderNamesEqual(entry.first, header.first); });
        if (!present) {
            current.AddHeader(header.first, header.second);
        }
    }
    const auto& pipeline = _impl->Config.Pipeline;
    std::size_t retries = 0;
    for (;;) {
        try {
            if (cancellationToken.IsCancellationRequested()) {
                return MakeError<Response>(CancelledError());
            }
            if (pipeline.BeforeSend) {
                pipeline.BeforeSend(current, cancellationToken);
            }
            auto result = _impl->Dispatch(current, cancellationToken);
            if (!result) {
                return result;
            }
            if (pipeline.AfterReceive) {
                pipeline.AfterReceive(current, *result, cancellationToken);
            }
            if (cancellationToken.IsCancellationRequested()) {
                return MakeError<Response>(CancelledError());
            }
            if (retries >= pipeline.MaxRetries || !pipeline.ShouldRetry || !pipeline.ShouldRetry(current, *result, retries, cancellationToken)) {
                return result;
            }
            ++retries;
        } catch (const std::exception& exception) {
            Error error;
            error.What = Error::Code::Interceptor;
            error.Message = exception.what();
            return MakeError<Response>(error);
        } catch (...) {
            Error error;
            error.What = Error::Code::Interceptor;
            error.Message = "Request interceptor failed";
            return MakeError<Response>(error);
        }
    }
}

